import os
import subprocess
import flask
from flask import Flask, request, jsonify

app = Flask(__name__)

# Configuration
UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/tmp/uploads')
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'pdf'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/api/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to different format using system tools."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No file selected'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    output_format = request.form.get('format', 'png')

    # Save uploaded file
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    input_path = os.path.join(UPLOAD_DIR, file.filename)
    file.save(input_path)

    # Build conversion command
    output_filename = file.filename.rsplit('.', 1)[0] + '.' + output_format
    output_path = os.path.join(UPLOAD_DIR, output_filename)

    # Use ImageMagick convert for image operations
    cmd = f"convert {input_path} -resize 800x600 {output_path}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )
        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'details': result.stderr.decode()}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)

    return jsonify({
        'status': 'success',
        'output': output_filename,
        'download_url': f'/api/download/{output_filename}'
    })

@app.route('/api/download/<filename>')
def download_file(filename):
    """Download converted file."""
    filepath = os.path.join(UPLOAD_DIR, filename)
    if not os.path.exists(filepath):
        return jsonify({'error': 'File not found'}), 404
    return flask.send_file(filepath)

@app.route('/api/health')
def health():
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
